import java.util.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import static org.objectweb.asm.Opcodes.*;
/** Exact inverse: two original fatal cleanup gates and one native cancellation clone. */
final class VerifyDeathCancellation {
 static final String P="local/lito381/server/",C=P+"ClientSession",H=P+"CombatDeathCancellation",E="(L"+P+"BattleDeathmatchFatalityCatalog$Effect;)V";
 static void need(boolean value,String reason){if(!value)throw new AssertionError("death cancellation "+reason);}
 static AbstractInsnNode before(AbstractInsnNode n){return VerifyCombatPreservation.prior(n);}static AbstractInsnNode after(AbstractInsnNode n){return VerifyCombatPreservation.following(n);}
 static MethodNode copy(MethodNode m){var n=new MethodNode(m.access,m.name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(n);return n;}
 static void raw(ClassNode c){var counts=new TreeMap<String,Integer>();for(var m:c.methods)for(var n:m.instructions)if(n instanceof MethodInsnNode call&&call.owner.equals(H))counts.merge(call.name,1,Integer::sum);need(counts.equals(new TreeMap<>(Map.of("death",2,"timed",1,"ability",1,"weapon",1,"cooking",4))),"exact hook counts "+counts);}
 static MethodNode normalize(MethodNode original){var m=copy(original);for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode call&&call.owner.equals(H)){
  if(call.name.equals("death")){need(Set.of("takePlayerDamage","takeClassicWorldDirectDamage").contains(m.name)&&call.desc.equals("(L"+C+";)V"),"only native fatal HP kernels");need(before(call) instanceof VarInsnNode actor&&actor.getOpcode()==ALOAD&&actor.var==0,"same original victim");var self=after(call);var field=after(self);var clear=after(field);need(self instanceof VarInsnNode a&&a.getOpcode()==ALOAD&&a.var==0&&field instanceof FieldInsnNode f&&f.getOpcode()==GETFIELD&&f.owner.equals(C)&&f.name.equals("timedStatus")&&clear instanceof MethodInsnNode c&&c.owner.equals(P+"BattleTimedStatus")&&c.name.equals("clearWaterDragonAffliction"),"immediately before original fatal cleanup anchor");m.instructions.remove(before(call));m.instructions.remove(call);continue;}
  if(call.name.equals("cooking")){need(Set.of("sourceDeathCancellation","applyFatalityCancellation","useCancellationSpell","useWorldPlayerCancellation").contains(m.name)&&call.desc.equals("(L"+P+"BattleCookingStatus;)Ljava/util/List;"),"same native cancellation cooking receiver/return");m.instructions.set(call,new MethodInsnNode(INVOKEVIRTUAL,P+"BattleCookingStatus","clear","()Ljava/util/List;",false));continue;}
  need(m.name.equals("sourceDeathCancellation"),"death-only adapters stay in private native clone");
  String type=switch(call.name){case "timed"->"BattleTimedStatus$MagicCancellation";case "ability"->"BattleAbilityStatus$Cancellation";case "weapon"->"BattleWeaponBuffStatus$Cancellation";default->throw new AssertionError("unknown death adapter");};need(call.desc.equals("(L"+P+type+";L"+C+";)L"+P+type+";"),"same original cancellation result type");need(before(call) instanceof VarInsnNode actor&&actor.getOpcode()==ALOAD&&actor.var==0,"same clone victim operand");var old=before(before(call));need(old instanceof MethodInsnNode base&&switch(call.name){case "timed"->base.owner.equals(P+"CombatNpcPoison")&&base.name.equals("cancelMagic");case "ability"->base.owner.equals(P+"BattleAbilityStatus")&&base.name.equals("cancelMagicEffects");case "weapon"->base.owner.equals(P+"BattleWeaponBuffStatus")&&base.name.equals("cancelMagicEffects");default->false;},"adapter immediately after original state capture");m.instructions.remove(before(call));m.instructions.remove(call);
 }return m;}
 static void clone(MethodNode clone,MethodNode nativeTrap){need(clone!=null&&nativeTrap!=null&&clone.desc.equals(E)&&clone.access==ACC_PRIVATE&&clone.exceptions.equals(nativeTrap.exceptions),"private native clone header");var restored=normalize(clone);var expected=copy(nativeTrap);int graphics=0;for(var n:expected.instructions.toArray())if(n instanceof MethodInsnNode call&&call.owner.equals(C)&&call.name.equals("broadcastFatalityEffect")){var list=before(call);var actor=before(list);var effect=before(actor);var self=before(effect);need(list instanceof MethodInsnNode factory&&factory.owner.equals("java/util/List")&&factory.name.equals("of")&&actor instanceof VarInsnNode a&&a.getOpcode()==ALOAD&&a.var==0&&effect instanceof VarInsnNode e&&e.getOpcode()==ALOAD&&e.var==1&&self instanceof VarInsnNode s&&s.getOpcode()==ALOAD&&s.var==0,"remove only original trap graphic operands");for(var removed:List.of(self,effect,actor,list,call))expected.instructions.remove(removed);graphics++;}need(graphics==1,"one trap graphic excluded; no death cast effect");for(var n:restored.instructions)need(!(n instanceof VarInsnNode v&&v.var==1),"unused Effect parameter never read by death clone");restored.name=expected.name;need(VerifyCombatPreservation.semantic(restored).equals(VerifyCombatPreservation.semantic(expected)),"native state capture, recipient/publisher, monitors and exception flow retained outside four declared death policies");}
}
